    instructionI18n: { "ja": "文脈に合う最も自然な文法を選び、空欄を埋めてください。", "en": "Fill in the blank: choose the grammar that fits the context most naturally." },
    promptText: "妹は 体調が 悪いのに、病院に ___ 。",
