    explanationI18n: { "ja": "「動詞の意向形＋とする」は「まさに～しようとする（そこで中断されたり別のことに気づいたりする）」ことを表します。「Vるとする」は別の意味で「～と仮定する」、「Vてとする」「Vたとする」はどちらも成り立ちません。", "en": "「volitional form + とする」means \"to be just about to do something\" (only to be interrupted or to notice something else). 「Vるとする」has the different meaning \"supposing that...\"; 「Vてとする」and 「Vたとする」are both ungrammatical." },
