    explanationI18n: { "ja": "「N＋らしい」はここでは「Nが本来持つべき特質を備えている」という意味で、典型を表し、伝聞ではありません。「ような」「みたいな」は「Nに似ている」（外見が似ている）、「そうな」は「～に見える」という意味です。", "en": "Here 「N + らしい」means \"having the qualities one expects of N\"—it's about being typical, not hearsay. 「ような」and 「みたいな」mean \"resembling N\" (similar in appearance); 「そうな」means \"looks like.\"" },
