    explanationI18n: { "ja": "「Vば＋Vほど」は「～すればするほど」を表し、前後の動詞は一致させます。「したほど」は過去形で成り立たず、「するばかり」は「ますます～」（一方向）、「するまで」は「～するまで」という意味です。", "en": "「Vば + Vほど」means \"the more..., the more...,\" and the verb must be the same before and after. 「したほど」in the past tense is ungrammatical; 「するばかり」means \"more and more\" (one-directional); 「するまで」means \"until.\"" },
