    explanationI18n: { "ja": "「Vた／イ形容詞＋のに」は「～なのに…」という逆接を表します。「ので」は順接の因果、「ように」は「～のために／～のように」、「うちに」は「～する間に」という意味です。", "en": "「Vた/i-adjective + のに」expresses the contrast \"even though..., yet...\" 「ので」is a straightforward cause-and-effect connective; 「ように」means \"in order to / like\"; 「うちに」means \"while (there's still time).\"" },
