    explanation: "「似合う」是「相襯、適合」，本句「那件藍襯衫很適合你」。「間に合う」是「來得及」；「付き合う」是「交往、陪同」；「似ている」是「相像」（近形陷阱，但「シャツが君に似ている」不通）。唯「似合う」成立。",
