    meaningI18n: { "ja": "慣れる（適応する）", "en": "get used to / adjust to" },
    promptLabel: "詞彙填空",
    instructionZh: "句中填空：選最自然的詞語。",
    instructionI18n: { "ja": "文中の空欄：最も自然な語を選びましょう。", "en": "Fill in the blank: choose the most natural word." },
    promptText: "新しい仕事に ___ まで、少し時間がかかった。",
    promptContextZh: "直到適應新工作，花了一點時間。",
    promptContextI18n: { "ja": "新しい仕事に慣れるまで、少し時間がかかりました。", "en": "It took a little time until I got used to the new job." },
    hintZh: "對新工作從陌生到上手的過程。",
    hintI18n: { "ja": "新しい仕事に、不慣れな状態から慣れていく過程を考えましょう。", "en": "The process of going from unfamiliar to comfortable with the new job." },
    expectedAnswer: "慣れる",
    options: ["慣れる", "慣らす", "困る", "飽きる"],
    explanation: "「慣れる」是「習慣、適應」，本句「直到適應新工作花了點時間」。「慣らす」是「使習慣（他動）」，與「仕事に」自動詞語境不合；「困る」是「為難」；「飽きる」是「厭倦」。唯「慣れる」成立。",
    explanationI18n: { "ja": "「慣れる」は「慣れる・適応する」を表し、本文では「新しい仕事に慣れるまで少し時間がかかった」となります。「慣らす」は「（他動詞で）慣れさせる」で、「仕事に」という自動詞の文脈には合いません。「困る」は「困る」、「飽きる」は「飽きる」です。成り立つのは「慣れる」だけです。", "en": "「慣れる」means \"get used to / adjust to\"; here \"it took a while to get used to the new job.\" 「慣らす」means \"to make (something) accustomed (transitive),\" which doesn't fit the intransitive 「仕事に」context; 「困る」means \"to be troubled\"; 「飽きる」means \"to grow tired of.\" Only 慣れる works." },
