    explanationI18n: { "ja": "「預ける」は「（自分の物を）相手に預けて保管してもらう」を表し、本文では「犬をペットホテルに預ける」となります。「預かる」は方向が逆で「（相手の物を）保管する」、「借りる」は「借りる」、「育てる」は「育てる」です（場所には「で」を使い、旅行中の一時的な預け入れと長期的に育てることは意味が合いません）。主語が犬を一時的にホテルに預けて任せる文脈なので、成り立つのは「預ける」だけです。", "en": "「預ける」means \"to leave (something) in another's care\"; here \"leave the dog at a pet hotel.\" 「預かる」is the opposite direction, \"to keep (something) for someone\"; 「借りる」means \"to borrow\"; 「育てる」means \"to raise\" (a place would take 「で」, and temporary boarding during a trip doesn't match long-term raising anyway). The subject temporarily hands the dog over to the hotel to look after, so only 預ける works." },
