    explanationI18n: { "ja": "物がその場に残るときは自動詞「残る」（残っている）を使います。「余る」は多く出て余ることで、かばん一つは「余る」とは言いません。「残す」は他動詞で主語はふつう人なので「かばんが残して」は成り立ちません。「かばんが置いていた」も不自然で、正しくは「置いてあった」となります。正解は「残って」だけです。", "en": "When an object remains in place, use the intransitive verb 「残る」(残っている). 「余る」means to be surplus or left over, and a single bag isn't 「余る」; 「残す」is transitive and its subject is usually a person (「かばんが残して」is ungrammatical); 「かばんが置いていた」is unnatural—it should be 「置いてあった」. Only 「残って」works." },
