    hintI18n: { "ja": "電池が切れるのは「なくなる／切れる」、食べ物が悪くなるのは「腐る」、花がしおれるのは「枯れる」で、これらの主語には使えない。", "en": "A dead battery is なくなる/切れる, food going bad is 腐る, and a wilting flower is 枯れる — none of those subjects take this word." },
    expectedAnswer: "一日中歩いたので、足がとても疲れた。",
