    instructionZh: "選出該詞語使用最自然的句子。",
    instructionI18n: { "ja": "その語の使い方が最も自然な文を選びましょう。", "en": "Choose the sentence where the word is used most naturally." },
    promptText: "次の文のうち、「比べる」の使い方が最も適切なものはどれか。",
    promptContextZh: "比較了兩家店的價格之後，才決定要在哪家店買。",
