    explanationI18n: { "ja": "「守る」は（規則を）守る、保護することです。「破る」は（規則を）破る・違反すること、「作る」は作ること、「覚える」は記憶することです。「ルールを…ことはみんなが安全に」と結びついて規則を守る意味を表すのは「守る」だけです。", "en": "「守る」= to follow (rules), to protect. 「破る」means to break or violate (a rule); 「作る」means to make; 「覚える」means to memorize. Pairing with \"following the rules is important for everyone's safety,\" only 「守る」works." },
