    explanationI18n: { "ja": "「包む」＝紙や布で物をくるむこと。「折る」は折り曲げること、「結ぶ」は縛って結び目を作ること、「混ぜる」は混ぜ合わせることです。「紙で…リボンをつけた」と結びついてプレゼント全体を覆う文脈なので、「包んだ」だけが成り立ちます。", "en": "「包む」means to wrap something up in paper or cloth. 「折る」is to fold; 「結ぶ」is to tie or knot; 「混ぜる」is to mix. Since the present is being fully covered with paper and given a ribbon (「紙で…リボンをつけた」), only 「包んだ」fits." },
