    explanationI18n: { "ja": "「細かい」＝細かく、こまごましたこと。「細かいところまで」で細部まで気を配る意味になります。「深い」は深いこと、「高い」は高いこと、「広い」は広いことです。「作業は…ところまで注意が必要」（細部に注意）と結びつくのは「細かい」だけです。", "en": "「細かい」means fine, small, or detailed, and 「細かいところまで」means attending even to the details. 「深い」is deep; 「高い」is high; 「広い」is wide. With 「作業は…ところまで注意が必要」 (paying attention to details), only 「細かい」fits." },
