    explanationI18n: { "ja": "「文化」は「ぶんか」と読みます。「ぶんが」は化を誤って濁らせたもの、「ふんか」は噴火（火山が噴き出すこと）でこの語ではなく、「ぶか」は「ん」が抜けたものです。", "en": "「文化」is read 「ぶんか」. 「ぶんが」wrongly voices 化; 「ふんか」is 噴火 (volcanic eruption), not this word; 「ぶか」drops the ん." },
