    explanation: "正解=あぶら。訓読み あぶら。干擾あふら＝把濁音 ぶ 誤讀成清音 ふ（清濁混淆，無此語）；あぶろ＝把尾音 ら 誤讀成 ろ（近形假名混淆，無此語）；あむら＝把 ぶ 誤讀成同為雙唇音的鼻音 む（子音混淆，無此語）。語境「フライパンに～を入れて」只接受あぶら。",
    explanationI18n: { "ja": "正解＝あぶら。訓読み あぶら。誤答あふら＝濁音 ぶ を清音 ふ と読み違えたもの（清濁の混同で、そのような語はありません）。あぶろ＝末尾 ら を ろ と読み違えたもの（形の近い仮名の混同で、そのような語はありません）。あむら＝ぶ を同じ唇音の鼻音 む と読み違えたもの（子音の混同で、そのような語はありません）。文脈「フライパンに～を入れて」ではあぶらしか受け入れられません。", "en": "The answer is あぶら, the kun'yomi あぶら. The distractor あふら misreads the voiced ぶ as the voiceless ふ (voicing confusion; not a real word); あぶろ misreads the final ら as ろ (similar-kana confusion; not a real word); あむら misreads ぶ as the bilabial nasal む (consonant confusion; not a real word). The context 「フライパンに～を入れて」 only accepts あぶら." },
