    instructionI18n: { "ja": "文中穴埋め:いちばん自然な語を選びましょう。", "en": "Fill in the blank: choose the most natural word." },
    promptText: "二人の友情が ___ に続くことを、心から願っている。",
    promptContextZh: "由衷希望兩人的友情能永遠持續下去。",
    promptContextI18n: { "ja": "二人の友情が永遠に続くことを、心から願っている。", "en": "I sincerely hope the two of them stay friends forever." },
    hintZh: "時間上沒有盡頭、一直延續不斷的狀態。",
    hintI18n: { "ja": "時間的に終わりがなく、ずっと続いていく状態。", "en": "A state with no end in time, continuing on and on." },
    expectedAnswer: "永遠",
    options: ["永遠", "一瞬", "当分", "偶然"],
    explanation: "「永遠に続く」＝一直持續下去。「一瞬」是一瞬間(時間極短、反義)；「当分」是暫時、一陣子；「偶然」是碰巧，皆不合「友情長久持續」的語境。",
    explanationI18n: { "ja": "「永遠に続く」でずっと続いていくことを表します。「一瞬」はほんの一瞬(時間がきわめて短く、反対の意味)、「当分」はしばらく・当面、「偶然」はたまたまで、いずれも「友情が長く続く」という文脈には合いません。", "en": "「永遠に続く」means \"to continue forever.\" 「一瞬」means a single instant (an extremely short time — the opposite); 「当分」means for a while, for the time being; 「偶然」means by chance — none fits the context of a friendship lasting a long time." },
