    hintZh: "在陌生的地方找不到方向、繞不出去。",
    hintI18n: { "ja": "知らない場所で方向が分からなくなり、抜け出せなくなること。", "en": "Losing your bearings in an unfamiliar place and not being able to find your way out." },
    expectedAnswer: "迷って",
    options: ["迷って", "困って", "慌てて", "焦って"],
    explanation: "「道に迷う」是固定搭配＝迷路。「困る」「慌てる」「焦る」雖都是情緒或狀態，但不與「道に」搭配表示迷路，故此處不成立。",
    explanationI18n: { "ja": "「道に迷う」は決まった言い方で、道に迷うことを表します。「困る」「慌てる」「焦る」はどれも感情や状態ですが、「道に」と結びついて道に迷う意味を表すことはないので、ここでは成り立ちません。", "en": "「道に迷う」is a set phrase meaning \"to get lost.\" 「困る」「慌てる」「焦る」are all emotions or states, but none pairs with「道に」to mean getting lost, so they don't work here." },
