    instructionI18n: { "ja": "語順の組み立て：文法的に正しく、意味の自然な文を選びましょう。", "en": "Word order: choose the sentence that is grammatically correct and natural in meaning." },
    promptText: "［いくら / 練習しても / 上手に / ならない］",
